-- Save MJ: AI Agent Types (core SP call only)
DECLARE @PromptParamsSchema_5f0af2b401e3 NVARCHAR(MAX),
@ID_5f0af2b401e3 UNIQUEIDENTIFIER
SET
  @PromptParamsSchema_5f0af2b401e3 = N'{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "description": "Prompt parameters for Loop Agent Type. Controls which sections are included in the system prompt to optimize token usage.",
  "properties": {
    "includeResponseTypeDefinition": {
      "type": "object",
      "description": "Control response type definition inclusion. Sections auto-align with their corresponding docs flags unless explicitly set.",
      "default": {
        "payload": true,
        "responseForms": true,
        "commands": true,
        "forEach": true,
        "while": true
      },
      "properties": {
        "payload": {
          "type": "boolean",
          "default": true,
          "description": "Include payloadChangeRequest type. Auto-aligns with includePayloadInPrompt."
        },
        "responseForms": {
          "type": "boolean",
          "default": true,
          "description": "Include responseForm type. Auto-aligns with includeResponseFormDocs."
        },
        "commands": {
          "type": "boolean",
          "default": true,
          "description": "Include actionableCommands/automaticCommands types. Auto-aligns with includeCommandDocs."
        },
        "forEach": {
          "type": "boolean",
          "default": true,
          "description": "Include ForEach in nextStep.type union. Auto-aligns with includeForEachDocs."
        },
        "while": {
          "type": "boolean",
          "default": true,
          "description": "Include While in nextStep.type union. Auto-aligns with includeWhileDocs."
        },
        "tasks": {
          "type": "boolean",
          "default": false,
          "description": "Include Tasks in nextStep.type union and the tasks property. Auto-aligns with enableTaskGraphs. Defaults to FALSE, unlike its siblings — an agent that has not opted into task graphs must not see the type at all, or the model will reach for it."
        }
      }
    },
    "includeForEachDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include ForEach operation documentation and examples. ForEach enables efficient batch processing of collections (e.g., processing all items in an array with a single LLM decision). Disable for agents that never need to iterate over collections."
    },
    "includeWhileDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include While loop documentation and examples. While loops enable polling, retrying, and conditional iteration (e.g., waiting for a job to complete). Disable for agents that never need polling or conditional loops."
    },
    "includeResponseFormDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include response form documentation for collecting structured user input. Response forms allow agents to request specific information from users via text fields, dropdowns, buttons, etc. Disable for agents that only output results and never need user input."
    },
    "includeCommandDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include actionable and automatic commands documentation. Actionable commands create clickable buttons (e.g., ''Open Record''), automatic commands trigger UI updates (e.g., refresh cache, show notification). Disable for agents that don''t need to provide navigation or trigger UI actions."
    },
    "includeMessageExpansionDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include message expansion documentation. Message expansion allows agents to request full content from previously compacted messages. Disable for agents that don''t use message compaction or don''t need to access compacted content."
    },
    "includeVariableRefsDocs": {
      "type": "boolean",
      "default": true,
      "description": "Include variable references documentation (payload.*, item.*, index, etc.). These explain how to reference data in action parameters and loop contexts. Disable if your agent''s custom examples already demonstrate variable usage patterns."
    },
    "includePayloadInPrompt": {
      "type": "boolean",
      "default": true,
      "description": "Include current payload state in the prompt. The payload is the agent''s working memory that persists across iterations. Disable for agents that don''t use the payload pattern or work purely from conversation context. Can save significant tokens for agents with large payloads."
    },
    "includeDateTimeInPrompt": {
      "type": "boolean",
      "default": true,
      "description": "Include current date, time, and day of week in the prompt. Provides the LLM with accurate temporal context so it doesn''t hallucinate dates or claim it doesn''t know the current time. Disable for agents where temporal context is irrelevant."
    },
    "specializationPlacement": {
      "type": "string",
      "enum": [
        "auto",
        "systemPrompt",
        "trailingMessage"
      ],
      "default": "auto",
      "description": "Where the agent''s child prompt (specialization) is placed. ''auto'' relocates it into the trailing message only if its template references a volatile placeholder (_CURRENT_DATE*, _CURRENT_TIME*, _CURRENT_PAYLOAD, _SCRATCHPAD_*) — a volatile child prompt mutates the system prompt every iteration ahead of the catalogs and history, so the runtime-state relocation alone recovers nothing for it. ''systemPrompt'' never relocates; ''trailingMessage'' always does. Decided once per run."
    },
    "trailingStateMode": {
      "type": "string",
      "enum": [
        "auto",
        "appendOnly",
        "replace"
      ],
      "default": "auto",
      "description": "How the trailing runtime-state message is carried across iterations. OpenAI''s automatic prompt cache only reuses a request whose entire prompt is a byte prefix of the new one, so replacing the fragment each iteration caps caching at the system prompt; retaining prior fragments and appending the new one keeps each request a prefix extension of the last. ''auto'' appends when the model catalog''s ModelConfiguration.LLM.PrefixPromptCache resolves to true for the serving path (Model Types < Models < Vendors'' Configuration.ModelDefaults < Model Vendors: the vendor''s defaults beat the model''s own bag and the inference provider''s row is the tie-breaker) and replaces otherwise; the answer is taken from the runtime model override or the first iteration''s model selection and then frozen for the run, so a failover never flips the layout. ''appendOnly'' forces append — use for a serving path whose catalog rows carry no flag yet. ''replace'' forces replace-in-place to keep context compact."
    },
    "decisionsEnabled": {
      "type": "boolean",
      "default": false,
      "description": "The master switch for decision-model use by this agent. Unless it is true, the agent never asks a decision model on its own, whatever the settings below say: inline decisions get no docs and no response field, and any request the model sends anyway is skipped, even with includeResponseTypeDefinition.decisions set to true; finishIf is treated as finishIfMode ''off'' (no docs, no field, no gate); decisionDiscovery, payloadFeedbackCheck and catalog narrowing (maxActionsInPrompt, maxSubAgentsInPrompt) do not run, so the prompt describes the whole catalog; and the Memory Manager''s note gate (enableDecisionGate) does not run. With it true, each of those settings works as documented, and each is still off by default. Explicit uses do not read it: a Flow agent''s Decision step, a task graph''s Decision step and the Run Decision action. Off by default."
    },
    "decisionsMaxCallsPerTurn": {
      "type": "integer",
      "minimum": 0,
      "default": 100,
      "description": "Maximum number of decision calls one turn''s decision requests make in total, counting every forEachItemIn item. Up to 8 requests (decisionsMaxRequests) of up to 100 items each (decisionsMaxItems) could otherwise send 800 calls in one turn, each with its own Decision step and prompt run, before the run''s MaxCostPerRun / MaxTokensPerRun checks (made between steps) could stop them. The budget is handed out in request order before any call is made: a forEachItemIn request it cuts short asks its first items and reports the rest in skippedCount, and a request it leaves no calls for is not run and gets a failed result saying why. 0 turns decision calls off: every request gets a failed result that says so, without inviting the agent to ask again."
    },
    "includeDecisionsDocs": {
      "type": "boolean",
      "default": false,
      "description": "Teach the model to request inline decisions (typed questions answered on the same turn by a decision model): the Decisions docs and the decisions field in the response type. Off by default: they add about 1,200 tokens to every turn, and on the Prompt Eval corpus no model used them (typed-decision plan, Task 4.7). Turn on for agents that classify, filter or route many items. Needs decisionsEnabled: true."
    },
    "finishIfMode": {
      "type": "string",
      "enum": [
        "off",
        "shadow",
        "on"
      ],
      "default": "off",
      "description": "Whether this agent writes finishIf gates (one to three yes/no questions and a final message on an Actions or single Sub-Agent step), and whether they act. ''off'' (the default): the model is not taught finishIf and a gate is never evaluated. ''shadow'': the model writes gates and each is evaluated and recorded as a Finish check step, but never ends the run, which measures the agent''s gates on real traffic. ''on'': a passing gate ends the run with the model''s message, without another LLM turn. Off by default because a replay of recorded action rounds found a gate at the 0.9 threshold would have ended 22% of the rounds where the agent went on to act (typed-decision plan, Task 4.6). Needs decisionsEnabled: true: without it the mode is treated as ''off''."
    },
    "payloadFeedbackCheck": {
      "type": "boolean",
      "default": false,
      "description": "Check the agent''s own payload changes that the payload analyzer flags as needing feedback (large truncations, removed keys, type changes). Each flagged change becomes one Likelihood (''was this change intended?''), all asked in one decision call with the decisionPromptName prompt and recorded as a ''Payload change check'' Decision step. The changes judged unintended are listed on the agent''s next turn, which asks it to confirm them or put them back. A change is never reverted or blocked automatically: the agent decides. When the decision fails or takes longer than 30 seconds, every change is accepted, as it is when this is off. A step that ends the run (Success, Chat, or any step that terminates) is not checked, since no turn would read the result. Off by default: each check costs an extra decision call. Needs decisionsEnabled: true."
    },
    "enableTaskGraphs": {
      "type": "boolean",
      "default": false,
      "description": "Allow this agent to emit durable task graphs (nextStep.type == ''Tasks''). DEFAULTS TO FALSE, unlike every other flag here, and is ENFORCED rather than advisory. The other flags only shape the prompt: turning one off saves tokens, and an agent that emits the feature anyway still works. This one is a capability gate — a task graph creates durable Task rows that outlive the run, execute on a server-side dispatcher under the submitting user, and can spawn further agent runs, so acquiring that reach through prompt drift rather than deliberate configuration is a real problem, not a token-budget one. LoopAgentType rejects a ''Tasks'' step from a disabled agent with a corrective, on top of omitting the type from the prompt."
    },
    "maxSubAgentsInPrompt": {
      "type": "integer",
      "default": -1,
      "description": "Catalog narrowing for sub-agents. -1 (the default) or 0 turns it off, and the prompt describes every sub-agent. A positive N: when the agent has more than N sub-agents, one decision call per run judges which are most useful for the run''s opening request, and the prompt describes those N plus any with MinExecutionsPerRun set, after a line naming the sub-agents it hides. Narrowing only hides: every permitted sub-agent can still be called by name, and a failed decision shows them all. It is prose-only: with native tool calling, every sub-agent is still declared as a tool. Setting N adds one decision call to each run. Needs decisionsEnabled: true: without it the prompt describes every sub-agent."
    },
    "maxActionsInPrompt": {
      "type": "integer",
      "default": -1,
      "description": "Catalog narrowing for actions and skills. -1 (the default) or 0 turns it off, and the prompt describes every action and skill. A positive N: when the agent has more than N actions (or skills), one decision call per run judges which are most useful for the run''s opening request, and the prompt describes those N plus any action with MinExecutionsPerRun set and the Find Candidate Actions / Find Candidate Agents actions, after a line saying how many it hides and how to reach them. Hidden skills are named; hidden actions are found with Find Candidate Actions, so actions are narrowed only when the agent has that action. Narrowing only hides: every permitted action and skill can still be used, and a failed decision shows them all. It is prose-only: with native tool calling, every action is still declared as a tool. Setting N adds one decision call to each run. Needs decisionsEnabled: true: without it the prompt describes every action and skill."
    },
    "clientToolResultMaxChars": {
      "type": "integer",
      "default": -1,
      "description": "Character cap for one client tool result in the conversation. -1 (the default) or 0 keeps the whole result. A positive N keeps the first N characters and adds a note saying how much was cut. Compaction and expiration still apply either way."
    },
    "decisionDiscovery": {
      "type": "boolean",
      "default": false,
      "description": "On a conversation''s opening request, before the first prompt, ask one typed decision which agent should handle it, and suggest it to the agent in a <suggested_agent> block. Follow-up turns are never asked about, so a suggestion never pulls the agent away from one it has already engaged. For conversation managers such as Sage. Off by default. Needs decisionsEnabled: true."
    }
